  } else if (s === 'personio' && typeof data === 'string') {
    const re = /<position>([\s\S]*?)<\/position>/g; let m;
    const tg = (b, t) => { const x = b.match(new RegExp('<' + t + '>([\\s\\S]*?)</' + t + '>')); return x ? x[1].replace(/^<!\[CDATA\[|\]\]>$/g, '').trim() : ''; };
    while ((m = re.exec(data))) {
