    const title = meta('og:title') || htmlToText((raw.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [, ''])[1]).trim();
    const host = (String(req.manualUrl || req.url).match(/^https?:\/\/(?:www\.)?([^/]+)/i) || [, ''])[1];
